usage:
// Client-side mirror of RespawnAnchorBlock.canSetSpawn(ServerLevel, BlockPos), which on the
// server is exactly:
//     level.environmentAttributes().getValue(EnvironmentAttributes.RESPAWN_ANCHOR_WORKS, pos)
// That expression compiles on a ClientLevel but is USELESS there: RESPAWN_ANCHOR_WORKS is not
// .syncable(), so DimensionType.NETWORK_CODEC strips it and the client always reads the
// attribute default (false) -- including in the Nether. Test the synced dimension-type identity
// instead; minecraft:the_nether is the only vanilla dimension type with respawn_anchor_works=true.

import net.minecraft.client.Minecraft;
import net.minecraft.client.multiplayer.ClientLevel;
import net.minecraft.core.BlockPos;
import net.minecraft.world.level.block.Blocks;
import net.minecraft.world.level.block.RespawnAnchorBlock;
import net.minecraft.world.level.block.state.BlockState;
import net.minecraft.world.level.dimension.BuiltinDimensionTypes;

public final class AnchorPredict {

    /** True if using the respawn anchor at {@code pos} would detonate it. */
    public static boolean wouldExplode(BlockPos pos) {
        ClientLevel level = Minecraft.getInstance().level;
        if (level == null) {
            return false;
        }
        BlockState state = level.getBlockState(pos);
        if (!state.is(Blocks.RESPAWN_ANCHOR) || state.getValue(RespawnAnchorBlock.CHARGE) == 0) {
            return false; // uncharged anchors just PASS, they never boom
        }
        return !anchorWorksHere(level);
    }

    /** THE single best client-side stand-in for EnvironmentAttributes.RESPAWN_ANCHOR_WORKS. */
    public static boolean anchorWorksHere(ClientLevel level) {
        return level.dimensionTypeRegistration().is(BuiltinDimensionTypes.NETHER);
    }

    /**
     * Proof, at runtime, that the attribute really is absent client-side: this returns false on
     * any client and true on a server holding the vanilla nether dimension type.
     */
    public static boolean attributeSurvivedSync(ClientLevel level) {
        return level.dimensionType()
                    .attributes()
                    .contains(net.minecraft.world.attribute.EnvironmentAttributes.RESPAWN_ANCHOR_WORKS);
    }
}
